import type { GameType } from '@sudoku-fight/engine';

import puzzles from './data/offline-puzzles.json';

/**
 * The puzzles that ship inside the app for practice (spec §16.1, §20): the engine bank's 'offline' pool,
 * at least 200 per game type. Generated by scripts/gen-offline-pool.mjs (`npm run pool`); ranked puzzles
 * never come here, because their solutions must not reach the phone (spec §21).
 */
export interface OfflinePuzzle {
  /** puzzleId(givens): the same id on the phone and on the server. */
  id: string;
  givens: string;
  solution: string;
  gameType: GameType;
}

/** Where a session finds its puzzles; tests pass a small one. */
export interface PuzzlePool {
  ids(gameType: GameType): readonly string[];
  byId(id: string): OfflinePuzzle | undefined;
}

const ALL = puzzles as OfflinePuzzle[];
const BY_ID = new Map(ALL.map((p) => [p.id, p]));
const IDS = new Map<GameType, string[]>();
for (const p of ALL) {
  const list = IDS.get(p.gameType) ?? [];
  list.push(p.id);
  IDS.set(p.gameType, list);
}

/** The ids of a game type's offline puzzles, in bank order. */
export const poolIds = (gameType: GameType): readonly string[] => IDS.get(gameType) ?? [];

export const puzzleById = (id: string): OfflinePuzzle | undefined => BY_ID.get(id);

/** Every offline puzzle (for tests and tools). */
export const allOfflinePuzzles = (): readonly OfflinePuzzle[] => ALL;

/** A pool made of a list of puzzles. */
export function poolOf(list: readonly OfflinePuzzle[]): PuzzlePool {
  const byId = new Map(list.map((p) => [p.id, p]));
  return {
    ids: (gameType) => list.filter((p) => p.gameType === gameType).map((p) => p.id),
    byId: (id) => byId.get(id),
  };
}

/** The app's pool. */
export const offlinePool: PuzzlePool = { ids: poolIds, byId: puzzleById };
